<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue';import NxAlert from'../../components/ui/NxAlert.vue';import NxBadge from'../../components/ui/NxBadge.vue';import NxButton from'../../components/ui/NxButton.vue';import NxCard from'../../components/ui/NxCard.vue';import NxModal from'../../components/ui/NxModal.vue';import NxPageHeader from'../../components/ui/NxPageHeader.vue';import NxTableShell from'../../components/ui/NxTableShell.vue';import NxToolbar from'../../components/ui/NxToolbar.vue';import{get,post,type Row}from'../technicians/api';
const loading=ref(false),busy=ref(false),error=ref(''),notice=ref(''),search=ref(''),users=ref<Row[]>([]),formOpen=ref(false),accessOpen=ref(false),editing=ref<Row|null>(null),selected=ref<Row|null>(null),permissions=ref<Row[]>([]),activeModule=ref(''),form=reactive<Row>({username:'',full_name:'',email:'',role:'SUPPORT',status:'ACTIVE',password:''});const inputClass='min-h-11 w-full rounded-md border border-[var(--nx-border)] bg-[var(--nx-surface)] px-3 text-sm text-[var(--nx-text)]';const currentUsername=()=>document.querySelector('.user-name')?.textContent?.trim()||'';const filtered=computed(()=>{const q=search.value.toLowerCase().trim();return users.value.filter(r=>!q||JSON.stringify(r).toLowerCase().includes(q));});const modules=computed(()=>[...new Set(permissions.value.map(p=>String(p.module_key||'other')))]);const modulePermissions=computed(()=>permissions.value.filter(p=>String(p.module_key||'other')===activeModule.value));const summary=computed(()=>({total:users.value.length,active:users.value.filter(r=>r.status==='ACTIVE').length,disabled:users.value.filter(r=>r.status==='DISABLED').length,admins:users.value.filter(r=>r.role==='SUPERADMIN').length}));const fmt=(v:any)=>v?new Date(String(v).replace(' ','T')).toLocaleString('en-PH'):'—';const tone=(v:any):'success'|'danger'|'warning'|'neutral'=>String(v).toUpperCase()==='ACTIVE'?'success':String(v).toUpperCase()==='DISABLED'?'danger':String(v).toUpperCase()==='SUPERADMIN'?'warning':'neutral';
async function load(show=false){loading.value=true;error.value='';try{const d=await get<any>('/api/v1/users');users.value=Array.isArray(d)?d:Array.isArray(d?.data)?d.data:[];if(show)notice.value='Users refreshed.';}catch(e){error.value=e instanceof Error?e.message:'Unable to load users.';}finally{loading.value=false;}}function openForm(r?:Row){editing.value=r||null;Object.assign(form,{username:r?.username||'',full_name:r?.full_name||'',email:r?.email||'',role:r?.role||'SUPPORT',status:r?.status||'ACTIVE',password:''});formOpen.value=true;}async function save(){busy.value=true;try{const payload={...form};if(editing.value)delete payload.password;await post(editing.value?`/api/v1/users/update/${editing.value.id}`:'/api/v1/users/store',payload);formOpen.value=false;notice.value=editing.value?'User updated.':'User created.';await load();}catch(e){error.value=e instanceof Error?e.message:'Unable to save user.';}finally{busy.value=false;}}
async function resetPassword(r:Row){const password=prompt(`New password for ${r.username} (minimum 8 characters):`)||'';if(password.length<8)return;busy.value=true;try{await post(`/api/v1/users/reset-password/${r.id}`,{password});notice.value='Password reset successfully.';}catch(e){error.value=e instanceof Error?e.message:'Unable to reset password.';}finally{busy.value=false;}}async function disable(r:Row){if(String(r.username).toLowerCase()===currentUsername().toLowerCase()){error.value='You cannot disable your own account.';return;}if(!confirm(`Disable ${r.username}?`))return;busy.value=true;try{await post('/api/v1/users/delete',{id:r.id});notice.value='User disabled.';await load();}catch(e){error.value=e instanceof Error?e.message:'Unable to disable user.';}finally{busy.value=false;}}
async function access(r:Row){selected.value=r;busy.value=true;try{const d=await get<any>(`/api/v1/users/${r.id}/permissions`);permissions.value=(d?.permissions||[]).map((p:Row)=>({...p,override_effect:String(p.override_effect||'INHERIT').toUpperCase()}));activeModule.value=String(permissions.value[0]?.module_key||'');accessOpen.value=true;}catch(e){error.value=e instanceof Error?e.message:'Unable to load permissions.';}finally{busy.value=false;}}function effective(p:Row){if(p.override_effect==='ALLOW')return true;if(p.override_effect==='DENY')return false;return !!p.role_allowed;}async function saveAccess(){if(!selected.value||selected.value.role==='SUPERADMIN')return;busy.value=true;try{const effects=Object.fromEntries(permissions.value.map(p=>[p.permission_key,p.override_effect]));await post(`/api/v1/users/${selected.value.id}/permissions`,{effects:JSON.stringify(effects)});accessOpen.value=false;notice.value='User permissions updated.';await load();}catch(e){error.value=e instanceof Error?e.message:'Unable to save permissions.';}finally{busy.value=false;}}
onMounted(()=>void load());
</script>
<template><div class="space-y-4 overflow-x-hidden pb-8 text-[var(--nx-text)]"><NxPageHeader eyebrow="Identity and access" title="Users & Access" description="Manage internal users, roles, account status, and individual RBAC permissions."><template #actions><NxButton :disabled="busy" @click="openForm()">Add User</NxButton><NxButton variant="secondary" :disabled="loading||busy" @click="load(true)">{{loading?'Refreshing…':'Refresh'}}</NxButton></template></NxPageHeader><NxAlert v-if="error||notice" :tone="error?'danger':'success'">{{error||notice}}</NxAlert><section class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><NxCard v-for="c in [['Total Users',summary.total,'Internal accounts'],['Active Accounts',summary.active,'Enabled access'],['Disabled',summary.disabled,'Access disabled'],['Superadmins',summary.admins,'Protected administrators']]" :key="String(c[0])"><p class="text-xs font-semibold uppercase text-[var(--nx-text-muted)]">{{c[0]}}</p><p class="mt-2 text-2xl font-bold">{{c[1]}}</p><p class="mt-1 text-xs text-[var(--nx-text-muted)]">{{c[2]}}</p></NxCard></section><NxToolbar><div class="flex flex-col gap-3 md:flex-row md:items-center md:justify-between"><div><h2 class="font-bold">Identity Directory</h2><p class="text-sm text-[var(--nx-text-muted)]">{{filtered.length}} system accounts</p></div><input v-model="search" type="search" placeholder="Search username, name, email, role…" :class="inputClass+' md:w-96'"></div></NxToolbar>
<NxTableShell min-width="1100px"><thead class="bg-[var(--nx-surface-muted)] text-xs uppercase"><tr><th class="px-4 py-3">User</th><th class="px-4 py-3">Email</th><th class="px-4 py-3">Role</th><th class="px-4 py-3">Status</th><th class="px-4 py-3">Access</th><th class="px-4 py-3">Last Login</th><th class="px-4 py-3">Created</th><th class="px-4 py-3 text-right">Actions</th></tr></thead><tbody><tr v-if="!filtered.length"><td colspan="8" class="p-12 text-center text-[var(--nx-text-muted)]">No users found.</td></tr><tr v-for="r in filtered" :key="r.id"><td class="px-4 py-3"><div class="flex items-center gap-3"><span class="grid h-9 w-9 place-items-center rounded-md bg-brand-100 font-bold text-brand-700">{{String(r.full_name||r.username||'U')[0].toUpperCase()}}</span><span><b>{{r.username}}</b><small class="block text-[var(--nx-text-muted)]">{{r.full_name||'—'}}</small></span></div></td><td class="px-4 py-3">{{r.email||'—'}}</td><td class="px-4 py-3"><NxBadge :tone="tone(r.role)">{{r.role}}</NxBadge></td><td class="px-4 py-3"><NxBadge :tone="tone(r.status)">{{r.status}}</NxBadge></td><td class="px-4 py-3"><NxButton variant="secondary" :disabled="busy" @click="access(r)">Manage Access</NxButton></td><td class="px-4 py-3">{{fmt(r.last_login)}}</td><td class="px-4 py-3">{{fmt(r.created_at)}}</td><td class="px-4 py-3"><div class="flex justify-end gap-2"><NxButton variant="secondary" @click="openForm(r)">Edit</NxButton><NxButton variant="secondary" @click="resetPassword(r)">Password</NxButton><NxButton variant="danger" :disabled="String(r.username).toLowerCase()===currentUsername().toLowerCase()||r.status==='DISABLED'" @click="disable(r)">Disable</NxButton></div></td></tr></tbody></NxTableShell>
<NxModal :open="formOpen" :title="editing?'Edit User':'Add User'" :description="editing?editing.username:'Create an internal system account'" max-width="48rem" @close="formOpen=false"><form id="user-current-form" class="grid gap-4 p-6 md:grid-cols-2" @submit.prevent="save"><label class="grid gap-2 text-sm font-semibold">Username<input v-model.trim="form.username" required :class="inputClass"></label><label class="grid gap-2 text-sm font-semibold">Full Name<input v-model.trim="form.full_name" required :class="inputClass"></label><label class="grid gap-2 text-sm font-semibold">Email<input v-model.trim="form.email" type="email" :class="inputClass"></label><label class="grid gap-2 text-sm font-semibold">Role<select v-model="form.role" :class="inputClass"><option v-for="r in ['SUPERADMIN','NOC','SUPPORT','BILLING','TECHNICIAN']" :key="r">{{r}}</option></select></label><label class="grid gap-2 text-sm font-semibold">Status<select v-model="form.status" :class="inputClass"><option>ACTIVE</option><option>DISABLED</option></select></label><label v-if="!editing" class="grid gap-2 text-sm font-semibold">Password<input v-model="form.password" type="password" minlength="8" required autocomplete="new-password" :class="inputClass"><small class="text-[var(--nx-text-muted)]">Minimum 8 characters.</small></label></form><template #footer><NxButton variant="secondary" @click="formOpen=false">Cancel</NxButton><NxButton type="submit" form="user-current-form" :disabled="busy">Save User</NxButton></template></NxModal>
<NxModal :open="accessOpen" title="User Access" :description="`${selected?.username||'User'} · ${selected?.role||'—'}`" max-width="76rem" @close="accessOpen=false"><div v-if="selected?.role==='SUPERADMIN'" class="m-6 rounded-md border border-amber-300 bg-amber-50 p-4 text-amber-900 dark:border-amber-800 dark:bg-amber-950/30 dark:text-amber-100"><b>Protected role:</b> Superadmin always has full access and cannot receive individual overrides.</div><div v-else class="grid min-h-[32rem] md:grid-cols-[220px_minmax(0,1fr)]"><aside class="border-b border-[var(--nx-border)] bg-[var(--nx-surface-muted)] p-3 md:border-b-0 md:border-r"><p class="px-2 pb-2 text-xs font-bold uppercase text-[var(--nx-text-muted)]">Modules</p><button v-for="m in modules" :key="m" class="flex w-full items-center justify-between rounded-md px-3 py-2 text-left text-sm font-semibold" :class="activeModule===m?'bg-brand-600 text-white':'hover:bg-[var(--nx-surface)]'" @click="activeModule=m"><span class="capitalize">{{m.replaceAll('-',' ')}}</span><small>{{permissions.filter(p=>p.module_key===m).length}}</small></button></aside><section class="min-w-0 p-4"><div class="mb-3"><p class="text-xs font-bold uppercase text-[var(--nx-text-muted)]">Module Permissions</p><h3 class="text-lg font-bold capitalize">{{activeModule.replaceAll('-',' ')}}</h3></div><NxTableShell min-width="760px"><thead class="bg-[var(--nx-surface-muted)] text-xs uppercase"><tr><th class="px-4 py-3">Action</th><th class="px-4 py-3 text-center">Inherit</th><th class="px-4 py-3 text-center">Allow</th><th class="px-4 py-3 text-center">Deny</th><th class="px-4 py-3">Effective</th></tr></thead><tbody><tr v-for="p in modulePermissions" :key="p.permission_key"><td class="px-4 py-3"><b class="capitalize">{{String(p.action_key).replaceAll('-',' ')}}</b><small v-if="p.is_sensitive" class="block text-amber-600">Sensitive action</small></td><td v-for="effect in ['INHERIT','ALLOW','DENY']" :key="effect" class="px-4 py-3 text-center"><input v-model="p.override_effect" type="radio" :name="`permission-${p.permission_key}`" :value="effect" :aria-label="`${effect} ${p.permission_key}`"></td><td class="px-4 py-3"><NxBadge :tone="effective(p)?'success':'danger'">{{effective(p)?'ALLOWED':'DENIED'}}</NxBadge><small class="block text-[var(--nx-text-muted)]">{{p.override_effect==='INHERIT'?'Role default':'User override'}}</small></td></tr></tbody></NxTableShell></section></div><template #footer><NxButton variant="secondary" @click="accessOpen=false">Cancel</NxButton><NxButton v-if="selected?.role!=='SUPERADMIN'" :disabled="busy" @click="saveAccess">Save Access</NxButton></template></NxModal></div></template>
<style scoped>:global([data-nx-next-root="users"]){max-width:100%;overflow-x:hidden}</style>
